public void updateDesignTemporary()
{
    boolean tempControl = NVTemporaryCheckbox.value();

    TempPosition_Control.visible(tempControl);
    TempPosition_Control.allowEdit(positionWorkerAssignmentActionState == HcmPositionWorkerAssignmentAction::Create);
    TempWorkerAssignmentOk.visible(tempControl);
    TempWorkerAssignmentOk.enabled(tempControl && TempPosition_Control.value() != 0);

    Position_Control.visible(!tempControl);
    PrimaryPositionCheckbox.visible(!tempControl);
    WorkerAssignmentOk.visible(!tempControl);

    if(Position_Control.value() != 0)
        TempPosition_Control.value(Position_Control.value());

    this.setTemporaryFormText();
}

private void setTemporaryFormText()
{
    if(positionWorkerAssignmentActionState == HcmPositionWorkerAssignmentAction::Edit)
    {
        TempWorkerAssignmentOk.text("@SYS320907");
    }

    else if(positionWorkerAssignmentActionState == HcmPositionWorkerAssignmentAction::End)
    {
        TempWorkerAssignmentOk.text("@SYS320908");
    }

}

public void performTemporaryAssignment()
{
    ttsbegin;
    HcmPositionWorkerAssignmentStartDate    validFrom   = DateTimeUtil::removeTimeZoneOffset(ValidFrom_Control.dateTimeValue(), userTimeZone);
    HcmPositionWorkerAssignmentEndDate      validTo     = DateTimeUtil::removeTimeZoneOffset(ValidTo_Control.dateTimeValue(), userTimeZone);

    HcmPositionWorkerAssignment temporaryWorkerAssignment;

    if(hcmPositionWorkerAssignment)
    {
        temporaryWorkerAssignment = HcmPositionWorkerAssignment::find(hcmPositionWorkerAssignment.RecId);
        temporaryWorkerAssignment.selectForUpdate(true);
        temporaryWorkerAssignment.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
    }

    temporaryWorkerAssignment.ValidFrom             = validFrom;
    temporaryWorkerAssignment.ValidTo               = validTo;
    temporaryWorkerAssignment.Worker                = Worker_Control.value();
    temporaryWorkerAssignment.Position              = TempPosition_Control.value();
    temporaryWorkerAssignment.AssignmentReasonCode  = ReasonCode_Control.value();
    temporaryWorkerAssignment.NVTempPosition        = NoYes::Yes;

    temporaryWorkerAssignment.write();
    ttscommit;
}

public void init()
{
    next init();

    if (this.args().caller())
    {
        switch (this.args().dataset())
        {
            case tableNum(HcmPositionWorkerAssignment):
                this.updateTemporaryPostionControl();
                break;
        }
    }

}

public HcmPositionWorkerAssignmentRecId createWorkerAssignmentOk()
{
    HcmPositionWorkerAssignmentRecId newWorkerAssignmentRecId = next createWorkerAssignmentOk();

    this.updateTemporaryPostion();

    NVPayrollWorkerReplaceEarningCode::existPosition(hcmPositionWorkerAssignment.Position, DateTimeUtil::date(hcmPositionWorkerAssignment.ValidFrom));

    return newWorkerAssignmentRecId;
}

public boolean editWorkerAssignmentOk()
{
    boolean isEditWorkerAssignmentSuccessful = next editWorkerAssignmentOk();

    this.updateTemporaryPostion();

    return true;
}

private void updateTemporaryPostion()
{
    ttsbegin;
    HcmPositionWorkerAssignment updPositionWorkerAssignment = HcmPositionWorkerAssignment::find(hcmPositionWorkerAssignment.RecId);
    updPositionWorkerAssignment.selectForUpdate(true);
    updPositionWorkerAssignment.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
    updPositionWorkerAssignment.NVTempPosition = NVTemporaryCheckbox.value();
    updPositionWorkerAssignment.doUpdate();
    ttscommit;
}
